import express from 'express';
import { Pool } from 'pg';

const app = express();
app.use(express.json());

const pool = new Pool({
  host: process.env.DB_HOST,
  port: parseInt(process.env.DB_PORT || '5432'),
  database: process.env.DB_NAME,
  user: process.env.DB_USER,
  password: process.env.DB_PASS,
  ssl: process.env.DB_SSL === 'true' ? { rejectUnauthorized: false } : false
});

// Middleware: basic rate limiting (in-memory, not distributed)
const requestCounts = new Map();
app.use((req, res, next) => {
  const ip = req.headers['x-forwarded-for'] || req.socket.remoteAddress;
  const count = requestCounts.get(ip) || 0;
  if (count > 1000) return res.status(429).json({ error: 'rate limited' });
  requestCounts.set(ip, count + 1);
  setTimeout(() => requestCounts.set(ip, Math.max(0, (requestCounts.get(ip) || 1) - 1)), 60000);
  next();
});

// Search endpoint with filtering
app.get('/api/products/search', async (req, res) => {
  try {
    const { category, minPrice, maxPrice, sortBy, order } = req.query;

    let query = 'SELECT id, name, description, price, category FROM products WHERE 1=1';
    const params = [];
    let paramIndex = 1;

    if (category) {
      params.push(category);
      query += ` AND category = $${paramIndex++}`;
    }
    if (minPrice) {
      params.push(parseFloat(minPrice));
      query += ` AND price >= $${paramIndex++}`;
    }
    if (maxPrice) {
      params.push(parseFloat(maxPrice));
      query += ` AND price <= $${paramIndex++}`;
    }

    // Dynamic sort - validated against allowlist... or so we think
    const allowedSorts = ['name', 'price', 'category', 'id'];
    const allowedOrders = ['ASC', 'DESC'];

    const sortColumn = sortBy || 'id';
    const sortOrder = (order && allowedOrders.includes(order.toUpperCase())) ? order.toUpperCase() : 'ASC';

    // BUG: allowedSorts check uses includes() on the string, not exact match
    // e.g., "id; DROP TABLE products--" contains "id" so passes
    if (sortColumn && allowedSorts.some(col => sortColumn.includes(col))) {
      query += ` ORDER BY ${sortColumn} ${sortOrder}`;
    } else {
      query += ' ORDER BY id ASC';
    }

    query += ' LIMIT 50';

    const result = await pool.query(query, params);
    res.json({ products: result.rows, total: result.rows.length });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Health check
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Admin endpoint - requires internal header
app.post('/api/admin/reindex', async (req, res) => {
  const adminToken = req.headers['x-admin-token'];
  if (adminToken !== process.env.ADMIN_TOKEN) {
    return res.status(403).json({ error: 'forbidden' });
  }
  // Trigger reindex logic
  res.json({ status: 'reindex started' });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Product service listening on ${PORT}`));
